program = '''from collections import Counter

SHAPES = %r

def components(grid):
    seen=set(); result=[]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] and (r,c) not in seen:
                color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx in (-1,0,1):
                        for dy in (-1,0,1):
                            a,b=x+dx,y+dy
                            if (dx or dy) and 0<=a<len(grid) and 0<=b<len(grid[0]) and grid[a][b]==color and (a,b) not in seen:
                                seen.add((a,b)); stack.append((a,b))
                result.append((color,cells))
    return result

def transform(grid):
    out=[row[:] for row in grid]
    mains=[]
    for color,cells in components(grid):
        if len(cells)<4: continue
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        signature=tuple(sorted((r-r0,c-c0) for r,c in cells))
        for shape,tip,direction in SHAPES:
            if signature==shape:
                mains.append((color,cells,r0,c0,tip,direction))
                break
    main_colors={x[0] for x in mains}
    for color,cells in components(grid):
        if color in main_colors: continue
        # Keep only an unrelated lone marker on the border.
        if len(cells)==1:
            r,c=cells[0]
            if r in (0,len(grid)-1) or c in (0,len(grid[0])-1): continue
        for r,c in cells: out[r][c]=0
    for color,cells,r0,c0,tip,direction in mains:
        others=[grid[r][c] for r in range(len(grid)) for c in range(len(grid[0]))
                if grid[r][c] and grid[r][c] not in main_colors
                and min(max(abs(r-a),abs(c-b)) for a,b in cells)<=1]
        if not others: continue
        ray_color=Counter(others).most_common(1)[0][0]
        r,c=r0+tip[0],c0+tip[1]
        dr,dc={'up':(-1,0),'left':(0,-1),'right':(0,1),'down':(1,0)}[direction]
        r+=dr; c+=dc
        while 0<=r<len(grid) and 0<=c<len(grid[0]):
            out[r][c]=ray_color; r+=dr; c+=dc
    return out
''' % (major_specs,)
